      141:                 op += 3;
      142:                 n -= 3;
      143:                 t0 = ToLinearF[(cr += wp[0]) & mask];
      144:                 t1 = ToLinearF[(cg += wp[1]) & mask];
      145:                 t2 = ToLinearF[(cb += wp[2]) & mask];
      146:                 op[0] = t0;
      147:                 op[1] = t1;
      148:                 op[2] = t2;
      149:             }
      150:         }
